 const heading=document.createElement('div');heading.className='game-title';
 const titles=document.createElement('div');const kicker=document.createElement('div');kicker.className='game-kicker';kicker.textContent='BATALLA NAVAL · TABLERO 10 × 10';
 const title=document.createElement('h1');title.textContent='Campo de batalla';
 const desc=document.createElement('p');desc.textContent=data.state==='finished'?'La partida terminó. Volvé al lobby para jugar otra vez.':data.turn?'Tu flota está lista. Marcá una coordenada enemiga para disparar.':'Esperando el disparo de '+(data.opponent||'tu rival')+'.';
 titles.append(kicker,title,desc);
 const badge=document.createElement('span');badge.className='turn-badge'+(data.turn?'':' wait');badge.textContent=data.state==='finished'?(data.winner?'🏆 VICTORIA':'PARTIDA FINALIZADA'):data.turn?'🎯 TU TURNO':'⏳ TURNO RIVAL';heading.append(titles,badge);panel.append(heading);
 const opponent=document.createElement('div');opponent.className='opponent-strip';
 const avatar=document.createElement('span');avatar.className='opponent-mark';avatar.textContent=(data.opponent||'R').trim().slice(0,1).toUpperCase();
 const info=document.createElement('div');info.className='opponent-info';const opponentLabel=document.createElement('div');opponentLabel.className='opponent-label';opponentLabel.textContent='RIVAL EN MESA';const opponentName=document.createElement('div');opponentName.className='opponent-name';opponentName.textContent=data.opponent||'Esperando rival';info.append(opponentLabel,opponentName);
 const stat=document.createElement('div');stat.className='opponent-stat';const hits=data.targetShots.filter(shot=>shot.hit).length;const attempts=data.targetShots.length;const statValue=document.createElement('strong');statValue.textContent=String(hits);const statLabel=document.createElement('span');statLabel.textContent='impactos · '+attempts+' tiros';stat.append(statValue,statLabel);opponent.append(avatar,info,stat);panel.append(opponent);
 if(data.state==='finished'){const result=document.createElement('div');result.className='game-result';result.textContent=data.winner?'✦ VICTORIA · FLOTILLA ENEMIGA DESTRUIDA':'PARTIDA FINALIZADA · GANÓ '+(data.opponent||'TU RIVAL').toUpperCase();panel.append(result)}
