  if(progress===57){let center=board.querySelector('.ludo-finish');if(!center){center=document.createElement('div');center.className='ludo-finish';center.style.gridRow='7 / span 3';center.style.gridColumn='7 / span 3';board.append(center)}center.append(tokenButton(player,token,progress));return}
  const coord=VladyerikLudo.boardCell(player,progress),cell=addCell(coord,progress<52?(VladyerikLudo.SAFE.has((VladyerikLudo.STARTS[player]+progress)%52)?'safe':'track'):'home-lane',player);cell.append(tokenButton(player,token,progress));
